<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Settings\SettingsService;use Vendi\Branches\BranchClock;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();$u=$_SESSION['user']??null;if(!$u){http_response_code(401);exit;}
$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);
$q=$db->prepare("SELECT s.*,b.name branch_name,b.legal_name,b.address_line1,b.address_line2,b.neighborhood,b.city,b.state,b.postal_code,b.phone,b.timezone,u.name user_name FROM sales s JOIN branches b ON b.id=s.branch_id JOIN users u ON u.id=s.user_id WHERE s.id=? AND s.business_id=?");$q->execute([(int)($_GET['id']??0),(int)$u['business_id']]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Venta no encontrada');}
$i=$db->prepare("SELECT description,qty,unit_price,discount,tax,line_total FROM sale_items WHERE sale_id=?");$i->execute([$s['id']]);$items=$i->fetchAll();$p=$db->prepare("SELECT COALESCE(pm.name,p.method) name,p.amount,p.change_amount,p.reference FROM payments p LEFT JOIN payment_methods pm ON pm.id=p.payment_method_id WHERE p.sale_id=?");$p->execute([$s['id']]);$payments=$p->fetchAll();
$settings=new SettingsService($db);$width=(int)$settings->get((int)$u['business_id'],(int)$s['branch_id'],'receipt.width_mm',80);if(!in_array($width,[58,80],true))$width=80;$margin=$width===58?2:3;$content=$width-($margin*2);$font=$width===58?10.5:12;$footer=(string)$settings->get((int)$u['business_id'],(int)$s['branch_id'],'receipt.footer','Gracias por su compra');$showAddress=$settings->get((int)$u['business_id'],(int)$s['branch_id'],'receipt.show_address','1')!=='0';$autoPrint=($_GET['print']??'')==='1';$when=!empty($s['completed_at_utc'])?(new BranchClock($db))->displayUtc((int)$u['business_id'],(int)$s['branch_id'],$s['completed_at_utc']):$s['completed_at'];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket #<?=$s['id']?></title><style>
:root{--paper:<?=$width?>mm;--content:<?=$content?>mm;--font:<?=$font?>px}*{box-sizing:border-box}@page{size:<?=$width?>mm auto;margin:<?=$margin?>mm}html,body{margin:0;padding:0;background:#eee}body{font-family:"Courier New",monospace;font-size:var(--font);line-height:1.25;color:#000}.ticket{width:var(--paper);max-width:100%;margin:12px auto;background:#fff;padding:<?=$margin?>mm}.center{text-align:center}.brand{font-size:1.45em;font-weight:800;margin:0}.muted{font-size:.88em}.rule{border-top:1px dashed #000;margin:6px 0}.items,.totals,.payments{width:100%;border-collapse:collapse;table-layout:fixed}.items td,.totals td,.payments td{vertical-align:top;padding:2px 0}.desc{overflow-wrap:anywhere}.money{text-align:right;white-space:nowrap;width:30%}.qty{font-size:.9em}.total{font-size:1.28em;font-weight:800}.actions{text-align:center;margin:12px}.actions button{padding:10px 18px}.footer{white-space:pre-wrap;overflow-wrap:anywhere}@media print{html,body{width:<?=$width?>mm;background:#fff}.ticket{width:<?=$content?>mm;margin:0;padding:0}.actions{display:none}}
</style></head><body><main class="ticket"><div class="center"><div class="brand"><?=htmlspecialchars($s['legal_name']?:$s['branch_name'])?></div><?php if($s['legal_name']):?><div><?=htmlspecialchars($s['branch_name'])?></div><?php endif;?><?php if($showAddress):?><div class="muted"><?=htmlspecialchars(trim(($s['address_line1']??'').' '.($s['address_line2']??'')))?><br><?=htmlspecialchars(trim(($s['neighborhood']??'').' '.($s['city']??'').' '.($s['state']??'').' '.($s['postal_code']??'')))?><?php if($s['phone']):?><br>Tel. <?=htmlspecialchars($s['phone'])?><?php endif;?></div><?php endif;?></div><div class="rule"></div><div>Venta #<?=$s['id']?></div><div><?=htmlspecialchars($when)?> · <?=htmlspecialchars($s['user_name'])?></div><div class="rule"></div><table class="items"><?php foreach($items as$x):?><tr><td class="desc"><?=htmlspecialchars($x['description'])?><div class="qty"><?=rtrim(rtrim(number_format((float)$x['qty'],3,'.',''),'0'),'.')?> × $<?=number_format((float)$x['unit_price'],2)?></div></td><td class="money">$<?=number_format((float)$x['line_total'],2)?></td></tr><?php endforeach;?></table><div class="rule"></div><table class="totals"><tr><td>Subtotal</td><td class="money">$<?=number_format((float)$s['subtotal'],2)?></td></tr><?php if((float)$s['discount']>0):?><tr><td>Descuento</td><td class="money">-$<?=number_format((float)$s['discount'],2)?></td></tr><?php endif;?><tr><td>IVA</td><td class="money">$<?=number_format((float)$s['tax'],2)?></td></tr><tr class="total"><td>TOTAL</td><td class="money">$<?=number_format((float)$s['total'],2)?></td></tr></table><div class="rule"></div><table class="payments"><?php foreach($payments as$pay):?><tr><td><?=htmlspecialchars($pay['name'])?><?php if($pay['reference']):?><div class="muted">Ref. <?=htmlspecialchars($pay['reference'])?></div><?php endif;?></td><td class="money">$<?=number_format((float)$pay['amount'],2)?></td></tr><?php if((float)$pay['change_amount']>0):?><tr><td>Cambio</td><td class="money">$<?=number_format((float)$pay['change_amount'],2)?></td></tr><?php endif;?><?php endforeach;?></table><div class="rule"></div><div class="center footer"><?=htmlspecialchars($footer)?></div></main><div class="actions"><button onclick="window.print()">Imprimir ticket <?=$width?> mm</button></div><?php if($autoPrint):?><script>addEventListener('load',()=>window.print())</script><?php endif;?></body></html>